{
  "shot": {
    "composition": "中景镜头，使用50mm标准变焦镜头，采用Sony Venice摄影机拍摄，景深控制在中等范围，确保主体清晰，背景适度虚化以突出人物情绪。",
    "camera_motion": "完全静止，无任何移动或摇晃，保持画面稳定，聚焦于人物面部与上半身，营造庄重、凝重的氛围。"
  },
  "subject": {
    "description": "一位约28岁的东亚洲女性，面容清冷而优雅，五官精致，眉目如画，眼眸深邃，透着一股冷冽的威严。她的黑发柔顺地垂落至肩部，发髻用紫色丝带轻巧束起，耳垂佩戴着小巧的珍珠耳坠，妆容精致，唇色淡雅，嘴角微扬，流露出一丝若有若无的笑意。",
    "wardrobe": "身着一袭淡粉色缎面改良式旗袍，领口与袖口饰有紫色盘扣，腰间系着同色系丝带，下身搭配米白色长裙，裙摆边缘绣有淡紫色云纹图案，整体造型典雅、端庄，带有古典韵味。"
  },
  "scene": {
    "location": "侯府内婚宴厅堂，装饰考究，木质结构与雕花窗格相映成趣，厅堂中央设有一张长桌，摆满酒席与茶点，背景墙上挂有书法字画，营造出浓郁的古典氛围。",
    "time_of_day": "正午时分，阳光透过雕花窗格洒入厅堂，光线柔和而明亮。",
    "environment": "厅堂内陈设典雅，地面铺有红金相间的地毯，两侧摆放着古朴的木制家具，桌上摆有酒杯、茶盏、果盘，背景墙上挂有水墨画与书法作品，空气中弥漫着淡淡的檀香与酒香，宾客们或坐或立，气氛热闹而庄重。"
  },
  "visual_details": {
    "action": "薛夫人冷冽地扫视全场宾客，嘴角勾起一抹意味深长的笑意，随后优雅地拿起酒杯，与宾客对饮，动作从容而自信。",
    "action_sequence": [
      "0-1s: 薛夫人缓缓抬眼，冷冽的视线从左至右扫过宾客，嘴角微扬，笑意如冰面裂开，带着一丝不易察觉的锋芒。",
      "1-2s: 她轻轻抬起右手，优雅地拿起酒杯，杯中盛满琥珀色的酒液，动作流畅而从容，眼神依旧冷峻，仿佛在审视每一个宾客。",
      "2-3s: 她将酒杯轻碰宾客的杯沿，发出清脆的碰撞声，嘴角笑意更深，眼神中透出一丝玩味与掌控。",
      "3-4s: 她轻抿一口酒，酒液在唇齿间流转，眼神依旧冷冽，但嘴角笑意已化为一抹温婉，仿佛在无声地宣告她的掌控与优雅。"
    ],
    "props": [
      "酒杯",
      "茶盏",
      "果盘",
      "雕花木桌",
      "书法字画",
      "檀香炉",
      "红色流苏灯笼"
    ]
  },
  "cinematography": {
    "lighting": "自然光从雕花窗格斜射入厅堂，形成柔和的光斑与阴影，光线主要集中在薛夫人面部与上半身，营造出戏剧性的明暗对比，突出她冷冽而优雅的气质。",
    "tone": "冷峻而优雅，带有一丝神秘与掌控感，画面色调偏暖，但人物面部与动作细节突出冷冽感，整体氛围庄重、凝重、充满张力。"
  }
}
